/// * `w:docPartBody` — Contents of Glossary Document Entry (§17.12.6)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CT_Body {
    /// Child elements of choice [`EG_BlockLevelElts`](crate::wml::EG_BlockLevelElts).
    pub block_level_elts: Vec<EG_BlockLevelElts>,
    /// `w:sectPr` — Document Final Section Properties (§17.6.17).
    pub sect_pr: Option<Box<CT_SectPr>>,
    /// Attributes not described by the schema, including namespace declarations.
    pub extra_attrs: Vec<RawAttribute>,
    /// Child elements not described by the schema, with their positions.
    pub extra_children: Vec<ExtraChild>,
}

impl XmlRead for CT_Body {
    fn read_xml(r: &mut XmlReader<'_>, tag: &StartTag<'_>) -> Result<Self> {
        let mut this = Self::default();
        for a in tag.attributes() {
            this.extra_attrs.push(a.to_raw());
        }
        if !tag.is_empty() {
            let mut pos: u16 = 0;
            while let Some(child) = r.next_child()? {
                match (child.ns(), child.local()) {
                    (Ns::W, "customXml")
                    | (Ns::W, "sdt")
                    | (Ns::W, "p")
                    | (Ns::W, "tbl")
                    | (Ns::W, "proofErr")
                    | (Ns::W, "permStart")
                    | (Ns::W, "permEnd")
                    | (Ns::W, "bookmarkStart")
                    | (Ns::W, "bookmarkEnd")
                    | (Ns::W, "moveFromRangeStart")
                    | (Ns::W, "moveFromRangeEnd")
                    | (Ns::W, "moveToRangeStart")
                    | (Ns::W, "moveToRangeEnd")
                    | (Ns::W, "commentRangeStart")
                    | (Ns::W, "commentRangeEnd")
                    | (Ns::W, "customXmlInsRangeStart")
                    | (Ns::W, "customXmlInsRangeEnd")
                    | (Ns::W, "customXmlDelRangeStart")
                    | (Ns::W, "customXmlDelRangeEnd")
                    | (Ns::W, "customXmlMoveFromRangeStart")
                    | (Ns::W, "customXmlMoveFromRangeEnd")
                    | (Ns::W, "customXmlMoveToRangeStart")
                    | (Ns::W, "customXmlMoveToRangeEnd")
                    | (Ns::W, "ins")
                    | (Ns::W, "del")
                    | (Ns::W, "moveFrom")
                    | (Ns::W, "moveTo")
                    | (Ns::M, "oMathPara")
                    | (Ns::M, "oMath")
                    | (Ns::W, "altChunk") => {
                        this.block_level_elts
                            .push(EG_BlockLevelElts::read_choice(r, &child)?);
                        pos = 1;
                    }
                    (Ns::W, "sectPr") => {
                        if this.sect_pr.is_none() {
                            this.sect_pr = Some(Box::new(XmlRead::read_xml(r, &child)?));
                        } else {
                            rt::push_extra(&mut this.extra_children, pos, RawElement::read(r, &child)?);
                        }
                        pos = 2;
                    }
                    _ => match pos {
                        1 => this
                            .block_level_elts
                            .push(EG_BlockLevelElts::Other(RawElement::read(r, &child)?)),
                        _ => rt::push_extra(&mut this.extra_children, pos, RawElement::read(r, &child)?),
                    },
                }
            }
        }
        Ok(this)
    }
}

impl XmlWrite for CT_Body {
    fn write_xml(&self, w: &mut XmlWriter, ns: Ns, local: &str) {
        w.start_with(ns, local, &self.extra_attrs);
        w.attrs_raw(&self.extra_attrs);
        rt::write_extras(w, &self.extra_children, 0);
        for v in &self.block_level_elts {
            v.write_choice(w);
        }
        rt::write_extras(w, &self.extra_children, 1);
        if let Some(v) = &self.sect_pr {
            v.write_xml(w, Ns::W, "sectPr");
        }
        rt::write_extras(w, &self.extra_children, 2);
        w.end();
    }
}

impl Validate for CT_Body {
    fn validate(&self, v: &mut Validator) {
        for (i, x) in self.block_level_elts.iter().enumerate() {
            x.validate_at(v, Some(i));
        }
        if let Some(x) = &self.sect_pr {
            v.enter("w:sectPr", None, |v| x.validate(v));
        }
    }
}

