/// Comments Collection (ECMA-376 Part 1 §17.13.4.6).
///
/// This element specifies all of the comments defined in the current document. It is the root element of the Comments part of a WordprocessingML document.
///
/// Schema type `CT_Comments`, used by:
///
/// * `w:comments` — Comments Collection (§17.13.4.6)
#[derive(Clone, Debug, Default, PartialEq)]
pub struct CT_Comments {
    /// `w:comment` — Comment Content (§17.13.4.2).
    pub comment: Vec<CT_Comment>,
    /// Attributes not described by the schema, including namespace declarations.
    pub extra_attrs: Vec<RawAttribute>,
    /// Child elements not described by the schema, with their positions.
    pub extra_children: Vec<ExtraChild>,
}

impl XmlRead for CT_Comments {
    fn read_xml(r: &mut XmlReader<'_>, tag: &StartTag<'_>) -> Result<Self> {
        let mut this = Self::default();
        for a in tag.attributes() {
            this.extra_attrs.push(a.to_raw());
        }
        if !tag.is_empty() {
            let mut pos: u16 = 0;
            while let Some(child) = r.next_child()? {
                match (child.ns(), child.local()) {
                    (Ns::W, "comment") => {
                        this.comment.push(XmlRead::read_xml(r, &child)?);
                        pos = 1;
                    }
                    _ => match pos {
                        1 => rt::push_extra_at(
                            &mut this.extra_children,
                            0,
                            this.comment.len(),
                            RawElement::read(r, &child)?,
                        ),
                        _ => rt::push_extra(&mut this.extra_children, pos, RawElement::read(r, &child)?),
                    },
                }
            }
        }
        Ok(this)
    }
}

impl XmlWrite for CT_Comments {
    fn write_xml(&self, w: &mut XmlWriter, ns: Ns, local: &str) {
        w.start_with(ns, local, &self.extra_attrs);
        w.attrs_raw(&self.extra_attrs);
        for (k, v) in self.comment.iter().enumerate() {
            rt::write_extras_at(w, &self.extra_children, 0, k);
            v.write_xml(w, Ns::W, "comment");
        }
        rt::write_extras_after(w, &self.extra_children, 0, self.comment.len());
        rt::write_extras(w, &self.extra_children, 1);
        w.end();
    }
}

impl Validate for CT_Comments {
    fn validate(&self, v: &mut Validator) {
        for (i, x) in self.comment.iter().enumerate() {
            v.enter("w:comment", Some(i), |v| x.validate(v));
        }
    }
}

