                    | (Ns::W, "sdt")
                    | (Ns::W, "p")
                    | (Ns::W, "tbl")
                    | (Ns::W, "proofErr")
                    | (Ns::W, "permStart")
                    | (Ns::W, "permEnd")
                    | (Ns::W, "bookmarkStart")
                    | (Ns::W, "bookmarkEnd")
