                    | (Ns::W, "bdo")
                    | (Ns::W, "r")
                    | (Ns::W, "proofErr")
                    | (Ns::W, "permStart")
                    | (Ns::W, "permEnd")
                    | (Ns::W, "bookmarkStart")
                    | (Ns::W, "bookmarkEnd")
                    | (Ns::W, "moveFromRangeStart")
                    | (Ns::W, "moveFromRangeEnd")
                    | (Ns::W, "moveToRangeStart")
                    | (Ns::W, "moveToRangeEnd")
                    | (Ns::W, "commentRangeStart")
                    | (Ns::W, "commentRangeEnd")
                    | (Ns::W, "customXmlInsRangeStart")
                    | (Ns::W, "customXmlInsRangeEnd")
                    | (Ns::W, "customXmlDelRangeStart")
                    | (Ns::W, "customXmlDelRangeEnd")
                    | (Ns::W, "customXmlMoveFromRangeStart")
                    | (Ns::W, "customXmlMoveFromRangeEnd")
                    | (Ns::W, "customXmlMoveToRangeStart")
                    | (Ns::W, "customXmlMoveToRangeEnd")
                    | (Ns::W, "ins")
                    | (Ns::W, "del")
                    | (Ns::W, "moveFrom")
                    | (Ns::W, "moveTo")
