        rt::write_attr(w, Ns::W, "rsidDel", &self.rsid_del);
        rt::write_attr(w, Ns::W, "rsidP", &self.rsid_p);
        rt::write_attr(w, Ns::W, "rsidRDefault", &self.rsid_r_default);
        w.attrs_raw(&self.extra_attrs);
        rt::write_extras(w, &self.extra_children, 0);
